return {
  name: 'novel-assistant-v10-host',
  apply(ctx) {
    const fs = ctx.get('fs')
    const sp = ctx.get('sandboxPolicy')
    if (fs === undefined || sp === undefined) return
    let seq = 0
    let loaded = false
    let rootCache = null
    const uid = (p) => p + (++seq)
    const clock = () => { try { return new Date().toISOString() } catch (e) { return '#' + (++seq) } }
    let state = {
      meta: { title: '', premise: '', genre: '', tone: '', targetLength: '', updatedAt: '' },
      settings: [],
      plot: { events: [] },
      seeds: [],
      outline: { arcs: [] },
      scenes: [],
      session: { activeSceneId: '', mode: 'idle', lastCheckId: '', startedAt: '' },
      candidates: [],
      inferences: [],
      log: [],
    }
    function findSession() {
      try {
        const agents = ctx.get('agents')
        if (!agents) return null
        const list = agents.list()
        for (const a of list) {
          const s = a.session || (a.ctx && a.ctx.session)
          if (s && s.meta && typeof s.meta.cwd === 'string' && s.meta.cwd) return s
        }
        return null
      } catch (e) { return null }
    }
    function policyForSession(session) {
      try {
        if (!session) return undefined
        const resolved = sp.resolve({ session: session })
        return resolved || undefined
      } catch (e) { return undefined }
    }
    function sessionCwd() {
      try {
        const agents = ctx.get('agents')
        if (!agents) return null
        const agent = agents.currentInitiator()
        if (!agent) return null
        if (typeof agent.cwd === 'string' && agent.cwd) return agent.cwd
        if (agent.session && agent.session.meta && typeof agent.session.meta.cwd === 'string' && agent.session.meta.cwd) return agent.session.meta.cwd
        if (agent.ctx && agent.ctx.session && agent.ctx.session.meta && typeof agent.ctx.session.meta.cwd === 'string' && agent.ctx.session.meta.cwd) return agent.ctx.session.meta.cwd
        if (typeof agent.sessionId === 'string') {
          const sessions = ctx.get('sessions')
          const s = sessions && sessions.get(agent.sessionId)
          if (s && s.meta && typeof s.meta.cwd === 'string' && s.meta.cwd) return s.meta.cwd
        }
        return null
      } catch (e) { return null }
    }
    function trimSlash(p) {
      while (p.length > 1 && (p.endsWith('/') || p.endsWith('\\'))) p = p.slice(0, -1)
      return p
    }
    async function readPointer() {
      try {
        const target = await fs.resolve('novel-assistant/.root', { cwd: sp.workspaceRoot || '.' })
        const info = await fs.stat(target)
        if (!info) return null
        const text = (await fs.readText(target)).trim()
        return text ? text : null
      } catch (e) { return null }
    }
    async function resolveRoot() {
      if (rootCache) return rootCache
      const cwd = sessionCwd()
      if (cwd) { rootCache = trimSlash(cwd); return rootCache }
      try {
        const probe = await fs.resolve('novel-assistant/state.json')
        const info = await fs.stat(probe)
        if (info) {
          const p = fs.processPath(probe)
          const idx = p.indexOf('novel-assistant')
          if (idx > 0) { rootCache = trimSlash(p.slice(0, idx)); return rootCache }
        }
      } catch (e) {}
      const ptr = await readPointer()
      if (ptr) { rootCache = trimSlash(ptr); return rootCache }
      rootCache = sp.workspaceRoot || '.'
      return rootCache
    }
    function rebuildSeq() {
      let max = 0
      const walk = (list) => list.forEach((o) => { const m = /(\d+)$/.exec(o.id || ''); if (m) { const n = parseInt(m[1], 10); if (n > max) max = n } })
      walk(state.settings)
      walk(state.plot.events)
      walk(state.seeds)
      state.outline.arcs.forEach((a) => { walk([a]); walk(a.chapters || []) })
      walk(state.scenes)
      walk(state.candidates)
      seq = max
    }
    async function ensureLoaded() {
      if (loaded) return
      loaded = true
      try {
        const root = await resolveRoot()
        const target = await fs.resolve(root + '/novel-assistant/state.json')
        const info = await fs.stat(target)
        if (info) {
          const parsed = JSON.parse(await fs.readText(target))
          if (parsed && parsed.meta) {
            state = parsed
            if (!state.settings) state.settings = []
            if (!state.plot) state.plot = { events: [] }
            if (!state.seeds) state.seeds = []
            if (!state.outline) state.outline = { arcs: [] }
            if (!state.scenes) state.scenes = []
            if (!state.session) state.session = { activeSceneId: '', mode: 'idle', lastCheckId: '', startedAt: '' }
            if (!state.candidates) state.candidates = []
            if (!state.inferences) state.inferences = []
            if (!state.log) state.log = []
            rebuildSeq()
          }
        }
      } catch (e) {
        console.error('[novel-assistant] load failed:', e && e.message)
      }
    }
    function pushLog(tool, note) {
      state.log.push({ at: clock(), tool: tool, note: note })
      if (state.log.length > 200) state.log.shift()
    }
    async function writeWithPolicy(relPath, content) {
      const root = await resolveRoot()
      const target = await fs.resolve(root + '/novel-assistant/' + relPath)
      const session = findSession()
      const policy = policyForSession(session)
      try {
        await fs.writeText(target, content, undefined, undefined, policy)
      } catch (e) {
        await fs.writeText(target, content, undefined, undefined, { mode: 'danger-full-access', workspaceRoot: root })
      }
      return target
    }
    async function persist() {
      try {
        await ensureLoaded()
        state.meta.updatedAt = clock()
        await writeWithPolicy('state.json', JSON.stringify(state, null, 2))
      } catch (e) {
        console.error('[novel-assistant] persist failed:', e && e.message)
      }
    }
    const SETTING_TYPES = ['world', 'character', 'faction', 'power', 'location', 'item', 'timeline', 'other']
    const EVENT_TYPES = ['开端', '发展', '转折', '高潮', '收束', '结局', '支线', '其他']
    const STATUSES = ['committed', 'candidate', 'rejected']
    const SEED_STATUSES = ['planted', 'growing', 'payoff', 'abandoned']
    const SEED_HORIZONS = ['短', '中', '长', '超长']
    const VERDICTS = ['大成功', '成功', '部分成功', '失败', '大失败']
    const CERTAINTIES = ['必然', '很可能', '可能', '低']
    const FOCUSES = ['武力', '术法', '智谋', '交涉', '隐秘', '感知', '意志', '其他']
    const CANDIDATE_KINDS = ['补全人物', '补全势力', '新建设定', '新增字段', '关联设定']
    const RANKS = ['凡人', '炼气', '筑基', '金丹', '元婴', '化神', '合体', '大乘', '渡劫']
    function findSetting(id) { return state.settings.find((s) => s.id === id) }
    function findEvent(id) { return state.plot.events.find((e) => e.id === id) }
    function findSeed(id) { return state.seeds.find((s) => s.id === id) }
    function findScene(id) { return state.scenes.find((s) => s.id === id) }
    function findCandidate(id) { return state.candidates.find((c) => c.id === id) }
    function render(_a, v) {
      return [{ type: 'text', text: typeof v === 'string' ? v : JSON.stringify(v, null, 2) }]
    }
    function registerTool(def) { harness.registerTool(ctx, harness.defineTool(def)) }
    function computeLayout() {
      const warnings = []
      const entities = {}
      state.settings.forEach((s) => {
        const entry = { id: s.id, name: s.name, type: s.type, state: {}, relations: (s.relations || []).slice() }
        ;(s.fields || []).forEach((f) => {
          const i = f.indexOf('：')
          if (i > 0) entry.state[f.slice(0, i).trim()] = f.slice(i + 1).trim()
          else if (i === -1) { const j = f.indexOf(':'); if (j > 0) entry.state[f.slice(0, j).trim()] = f.slice(j + 1).trim() }
        })
        entities[s.id] = entry
      })
      state.plot.events.filter((e) => e.status === 'committed').forEach((ev) => {
        ;(ev.world_delta || []).forEach((d) => {
          const m = /^([^:]+):([^:]+):(.*?)→(.*)$/.exec(d)
          if (!m) { warnings.push(ev.id + ' 无法解析的 world_delta：「' + d + '」'); return }
          const id = m[1].trim(), field = m[2].trim(), from = m[3].trim(), to = m[4].trim()
          const entry = entities[id]
          if (!entry) { warnings.push(ev.id + ' world_delta 指向不存在的设定 ' + id); return }
          const cur = entry.state[field]
          if (cur !== undefined && from && cur !== from) warnings.push(ev.id + ' world_delta 失配 ' + id + '.' + field + '：当前「' + cur + '」≠ 旧值「' + from + '」')
          entry.state[field] = to
        })
      })
      const pairMap = {}
      state.plot.events.filter((e) => e.status === 'committed').forEach((e) => {
        const b = e.conflict_between || []
        for (let i = 0; i < b.length; i++) {
          for (let j = i + 1; j < b.length; j++) {
            const key = [b[i], b[j]].sort().join('|')
            pairMap[key] = pairMap[key] || { a: b[i], b: b[j], events: [], count: 0 }
            pairMap[key].events.push(e.id)
            pairMap[key].count++
          }
        }
      })
      const conflicts = Object.keys(pairMap).map((k) => ({ pair: [pairMap[k].a, pairMap[k].b], events: pairMap[k].events, count: pairMap[k].count }))
      const factionMembers = {}
      state.settings.forEach((s) => {
        if (s.type !== 'faction') return
        const members = []
        state.settings.forEach((o) => {
          if (o.type !== 'character') return
          const linked = (o.relations || []).some((r) => r.indexOf(s.id + ' ') === 0 || r.indexOf(s.id + '：') === 0 || r.indexOf(s.id) === 0)
          if (linked) members.push(o.id)
        })
        factionMembers[s.id] = members
      })
      return { entities: entities, conflicts: conflicts, factionMembers: factionMembers, warnings: warnings }
    }
    // ============ v10：场景与检定引擎 ============
    function lastCommittedEvent() {
      const list = state.plot.events.filter((e) => e.status === 'committed')
      return list.length ? list[list.length - 1] : null
    }
    function activeScene() {
      return state.session.activeSceneId ? findScene(state.session.activeSceneId) : null
    }
    function checkActorState(actorId, layout) {
      const ent = layout.entities[actorId]
      if (!ent) return { ok: false, reason: '设定不存在：' + actorId }
      if (ent.type !== 'character') return { ok: true, note: '参与者不是人物卡（' + ent.type + '），跳过存活校验' }
      const st = ent.state['状态'] || ent.state['生死'] || ''
      if (st === '死亡' || st === '已死' || st === '陨落' || st === '身死') {
        return { ok: false, reason: actorId + '（' + ent.name + '）当前状态为「' + st + '」，不能参与行动；如确需以特殊方式行动请传 force=true 并说明依据' }
      }
      return { ok: true }
    }
    function rankOf(v) {
      const s = String(v || '').trim()
      const i = RANKS.indexOf(s)
      return i >= 0 ? i : -1
    }
    function compareCapability(actorId, others, layout) {
      // 尽力而为的机械对比：双方都有可识别境界/修为时给出提示
      const findRank = (id) => {
        const ent = layout.entities[id]
        if (!ent) return -1
        const r = rankOf(ent.state['境界'] || ent.state['修为'] || ent.state['实力'] || '')
        return r
      }
      const a = findRank(actorId)
      if (a < 0) return null
      const tips = []
      ;(others || []).forEach((oid) => {
        const b = findRank(oid)
        if (b >= 0 && b !== a) {
          const ent = layout.entities[oid]
          tips.push('对方 ' + (ent ? ent.name : oid) + ' 境界「' + (layout.entities[oid] && layout.entities[oid].state['境界'] || layout.entities[oid] && layout.entities[oid].state['修为'] || '?') + '」' + (b > a ? '高于' : '低于') + '行动者')
        }
      })
      return tips.length ? tips : null
    }
    function validateDeltas(deltas, layout) {
      const errors = []
      ;(deltas || []).forEach((d) => {
        const m = /^([^:]+):([^:]+):(.*?)→(.*)$/.exec(d)
        if (!m) { errors.push('无法解析 world_delta：「' + d + '」（格式 目标id:字段:旧值→新值）'); return }
        const id = m[1].trim(), field = m[2].trim(), from = m[3].trim(), to = m[4].trim()
        const ent = layout.entities[id]
        if (!ent) { errors.push('world_delta 目标设定不存在：' + id); return }
        const cur = ent.state[field]
        if (cur !== undefined && from && String(cur) !== from) errors.push('world_delta 失配 ' + id + '.' + field + '：当前「' + cur + '」≠ 旧值「' + from + '」（请以局势图当前值为准）')
        if (to === '') errors.push('world_delta 目标值不能为空：' + d)
      })
      return errors
    }
    function validateReasons(reasons) {
      const errors = []
      ;(reasons || []).forEach((r) => {
        const ids = r.match(/[a-z]+\d+/g) || []
        ids.forEach((id) => {
          if (!findSetting(id) && !findEvent(id) && !findSeed(id)) errors.push('依据引用了不存在的 id：' + id + '（在「' + r + '」中）')
        })
      })
      return errors
    }
    function sceneChecks(scene) { return scene.checks || [] }
    function commitCheckEvent(actorId, scene, args, layout) {
      const causes = args.causes && args.causes.length ? args.causes : (lastCommittedEvent() ? [lastCommittedEvent().id] : [])
      const ev = {
        id: uid('e'),
        seq: state.plot.events.length + 1,
        status: args.branch ? 'candidate' : 'committed',
        type: args.type || '发展',
        title: args.event_title || (scene ? '检定：' + args.action.slice(0, 12) + (args.action.length > 12 ? '…' : '') : args.action),
        summary: '[' + (actorId === 'env' ? '环境' : actorId) + ' 行动] ' + args.action + '。目标：' + args.goal + '。裁决：' + args.verdict + '（' + args.certainty + '）。结果：' + args.outcome,
        causes: causes,
        branch_of: args.branch ? (scene && scene.branch_of) || (causes.length ? causes[causes.length - 1] : null) : null,
        participants: actorId === 'env' ? [] : [actorId],
        location: (scene && scene.location) || '',
        conflict_between: (scene && scene.conflict_between) || [],
        stakes: (scene && scene.stakes) || '',
        world_delta: (args.world_delta || []).slice(),
        constraints: (scene && scene.constraints || []).slice(),
        at: clock(),
        check: { verdict: args.verdict, certainty: args.certainty, focus: args.focus || '', reasons: (args.reasons || []).slice() },
      }
      state.plot.events.push(ev)
      return ev
    }
    // ============ v10：反向推导（候选设定） ============
    function candidateExists(kind, targetName) {
      return state.candidates.some((c) => c.kind === kind && c.targetName === targetName && c.status === 'pending')
    }
    function addCandidate(kind, targetName, type, reason, evidence, proposed) {
      if (candidateExists(kind, targetName)) return null
      const c = {
        id: uid('p'),
        kind: kind,
        targetName: targetName,
        type: type || 'other',
        reason: reason,
        evidence: evidence || [],
        proposed: proposed || {},
        status: 'pending',
        at: clock(),
      }
      state.candidates.push(c)
      return c
    }
    function scanImpliedSettings() {
      const created = []
      const sIds = new Set(state.settings.map((s) => s.id))
      // 1) 事件 conflict_between / participants 中出现但未登记的 id 或名称
      const nameToId = {}
      state.settings.forEach((s) => { nameToId[s.name] = s.id })
      state.plot.events.forEach((e) => {
        ;(e.conflict_between || []).forEach((x) => {
          if (sIds.has(x) || nameToId[x]) return
          const c = addCandidate('新建设定', x, 'faction', '事件 ' + e.id + ' 的冲突双方引用了未登记的名称', [e.id], { name: x, type: 'faction' })
          if (c) created.push(c.id)
        })
      })
      // 2) 人物卡不完整（缺状态/能力字段）
      state.settings.forEach((s) => {
        if (s.type !== 'character') return
        const keys = (s.fields || []).map((f) => f.split(/[：:]/)[0].trim())
        const missing = []
        if (!keys.some((k) => k === '状态' || k === '生死')) missing.push('状态')
        if (!keys.some((k) => /能力|实力|境界|修为/.test(k))) missing.push('能力/境界/修为')
        if (missing.length) {
          const c = addCandidate('补全人物', s.name, 'character', '人物卡缺少字段：' + missing.join('、'), [], { id: s.id, name: s.name, type: 'character', fields: missing })
          if (c) created.push(c.id)
        }
      })
      // 3) 势力卡没有成员
      state.settings.forEach((s) => {
        if (s.type !== 'faction') return
        const members = state.settings.filter((o) => o.type === 'character' && (o.relations || []).some((r) => r.indexOf(s.id) === 0))
        if (!members.length) {
          const c = addCandidate('补全势力', s.name, 'faction', '势力卡尚无任何成员关系', [], { id: s.id, name: s.name, type: 'faction' })
          if (c) created.push(c.id)
        }
      })
      // 4) world_delta 修改了卡上不存在的字段
      state.plot.events.forEach((e) => {
        ;(e.world_delta || []).forEach((d) => {
          const m = /^([^:]+):([^:]+):/.exec(d)
          if (!m) return
          const sid = m[1].trim(), field = m[2].trim()
          const s = findSetting(sid)
          if (!s) return
          const keys = (s.fields || []).map((f) => f.split(/[：:]/)[0].trim())
          if (!keys.includes(field)) {
            const c = addCandidate('新增字段', s.name + '·' + field, s.type, '事件 ' + e.id + ' 改变了卡上不存在的字段「' + field + '」', [e.id], { id: sid, name: s.name, type: s.type, field: field })
            if (c) created.push(c.id)
          }
        })
      })
      // 5) 已埋设伏笔但没有关联设定
      state.seeds.forEach((s) => {
        if (s.status === 'abandoned') return
        if (!(s.related_settings || []).length) {
          const c = addCandidate('关联设定', '伏笔·' + s.title, 'other', '伏笔「' + s.title + '」未关联任何设定卡', [s.planted_at].filter(Boolean), { seedId: s.id, title: s.title })
          if (c) created.push(c.id)
        }
      })
      return created
    }
    // ============ v10：推理 ============
    function corpusFor(domain) {
      const corpus = { settings: [], events: [], seeds: [], layout: computeLayout(), scene: activeScene() }
      state.settings.forEach((s) => {
        if (!domain || domain === 'all' || s.type === domain || (domain === 'plot' && ['location', 'item'].includes(s.type))) corpus.settings.push(s)
      })
      corpus.events = state.plot.events.filter((e) => e.status === 'committed')
      corpus.seeds = state.seeds.slice()
      return corpus
    }
    // ============ 工具注册 ============
    registerTool({
      name: 'novel_init',
      description: '创建或重置小说项目（会覆盖当前项目）。这是项目的起点：只接收构思（标题+一句话核心构思），不接收正文。创建后按 设定→推演→大纲 顺序推进。',
      parameters: {
        title: { type: 'string', required: true, description: '作品名' },
        premise: { type: 'string', required: true, description: '一句话核心构思：主角、核心冲突、世界基调。结构化描述，非文学段落' },
        genre: { type: 'string', description: '题材，如 玄幻/科幻/悬疑/都市/武侠' },
        tone: { type: 'string', description: '风格基调，如 热血/冷峻/诙谐' },
        target_length: { type: 'string', description: '目标篇幅，如 200万字 或 中篇' },
      },
      output: { schema: { type: 'string' }, render: render },
      async execute(args) {
        await ensureLoaded()
        const oldTitle = state.meta.title
        state = {
          meta: { title: args.title, premise: args.premise, genre: args.genre || '', tone: args.tone || '', targetLength: args.target_length || '', updatedAt: clock() },
          settings: [],
          plot: { events: [] },
          seeds: [],
          outline: { arcs: [] },
          scenes: [],
          session: { activeSceneId: '', mode: 'idle', lastCheckId: '', startedAt: '' },
          candidates: [],
          inferences: [],
          log: [],
        }
        pushLog('novel_init', '创建项目：' + args.title)
        await persist()
        return '项目已创建：《' + args.title + '》' + (oldTitle ? '（覆盖了原项目《' + oldTitle + '》）' : '') +
          '\n核心构思：' + args.premise +
          '\n下一步：先用 novel_setting_upsert 建立世界观与核心人物（type=world / character），再开始推演。'
      },
    })
    registerTool({
      name: 'novel_state',
      description: '读取当前项目状态，用于推演前的上下文检索。view=overview 返回精简总览（含存储根目录 store 与伏笔统计）；view=settings 返回设定列表（可按 type/query 过滤）；view=plot 返回完整事件链；view=seeds 返回伏笔列表；view=outline 返回大纲；view=full 返回全部。',
      parameters: {
        view: { type: 'string', description: 'overview|settings|plot|seeds|outline|full，默认 overview' },
        type: { type: 'string', description: 'settings 视图下按类型过滤：world/character/faction/power/location/item/timeline/other' },
        query: { type: 'string', description: '按名称关键字过滤设定' },
      },
      output: { schema: { type: 'string' }, render: render },
      async execute(args) {
        await ensureLoaded()
        const view = args.view || 'overview'
        if (view === 'overview') {
          return JSON.stringify({
            meta: state.meta,
            store: await resolveRoot(),
            stats: {
              settings: state.settings.length,
              events: state.plot.events.length,
              committed: state.plot.events.filter((e) => e.status === 'committed').length,
              candidates: state.plot.events.filter((e) => e.status === 'candidate').length,
              seeds: state.seeds.length,
              seedsOpen: state.seeds.filter((s) => s.status === 'planted' || s.status === 'growing').length,
              arcs: state.outline.arcs.length,
              scenes: state.scenes.length,
              scenesOpen: state.scenes.filter((s) => s.status === 'open').length,
              pendingCandidates: state.candidates.filter((c) => c.status === 'pending').length,
            },
            chain: state.plot.events.filter((e) => e.status === 'committed').map((e) => e.id + ' ' + e.type + ' ' + e.title),
