        branch: { type: 'boolean', description: 'true=作为候选分支提交（status=candidate），由用户采纳其一；默认 false 直接采纳' },
        force: { type: 'boolean', description: 'true=跳过存活校验硬拦截（须在 reasons 说明特殊依据）' },
