        if (!c) return '候选不存在：' + args.id
        if (c.status !== 'pending') return '候选已处理（' + c.status + '）：' + args.id
        if (!args.accept) {
          c.status = 'rejected'
          pushLog('novel_candidate_decide', '忽略候选 ' + c.id + ' ' + c.targetName)
          await persist()
          return '已忽略候选 ' + c.id + '「' + c.targetName + '」'
        }
        // 采纳：按 kind 落实
        if (c.kind === '新建设定' || c.kind === '补全势力') {
          const name = args.name || (c.proposed && c.proposed.name) || ''
          const type = args.type || (c.proposed && c.proposed.type) || 'other'
          if (!name) return '采纳新建设定需要提供 name'
          const card = { id: uid('s'), type: type, name: name, summary: args.summary || ('由候选 ' + c.id + ' 建立：' + c.reason), fields: (args.fields || []).slice(), relations: [], tags: ['候选'] }
          state.settings.push(card)
          pushLog('novel_candidate_decide', '候选建卡 ' + card.id + ' ' + card.name)
          c.status = 'accepted'
          c.resultId = card.id
        } else if (c.kind === '补全人物' || c.kind === '新增字段') {
          const targetId = (c.proposed && c.proposed.id) || ''
          const card = findSetting(targetId)
          if (!card) return '候选指向的设定卡不存在：' + targetId + '（' + c.targetName + '）'
          const keys = (card.fields || []).map((f) => f.split(/[：:]/)[0].trim())
          const added = []
          ;(args.fields || []).forEach((f) => {
            const k = f.split(/[：:]/)[0].trim()
            if (k && !keys.includes(k)) { card.fields.push(f); added.push(k) }
          })
          if (args.summary) card.summary = args.summary
          pushLog('novel_candidate_decide', '候选补卡 ' + card.id + ' 新增字段 ' + added.join('、'))
          c.status = 'accepted'
          c.resultId = card.id
        } else if (c.kind === '关联设定') {
          const seed = findSeed((c.proposed && c.proposed.seedId) || '')
          if (seed) {
            const sids = (args.fields || []).filter((f) => findSetting(f.split(/[：:]/)[0].trim()))
            sids.forEach((f) => { const sid = f.split(/[：:]/)[0].trim(); if (!seed.related_settings.includes(sid)) seed.related_settings.push(sid) })
            pushLog('novel_candidate_decide', '候选关联伏笔 ' + seed.id)
          }
          c.status = 'accepted'
        } else {
          c.status = 'accepted'
        }
        await persist()
        return '已采纳候选 ' + c.id + '「' + c.targetName + '」' + (c.resultId ? ' → ' + c.resultId : '')
      },
    })
