      const ev = commitCheckEvent(a.actor || 'env', scene, { action: a.action, goal: a.goal, verdict: a.verdict, certainty: a.certainty || '可能', outcome: a.outcome, reasons: a.reasons, world_delta: a.world_delta, branch: !!a.branch, type: a.type || '发展', causes: a.causes, event_title: a.event_title }, layout)
      scene.checks.push({
        id: uid('ck'), actor: a.actor || 'env', action: a.action, goal: a.goal, approach: a.approach || '',
        focus: a.focus || '其他', verdict: a.verdict, certainty: a.certainty || '可能', outcome: a.outcome,
        reasons: (a.reasons || []).slice(), world_delta: (a.world_delta || []).slice(), eventId: ev.id, at: clock(),
      })
      scene.outcomeEvents.push(ev.id)
      state.session.lastCheckId = scene.checks[scene.checks.length - 1].id
      pushLog('scene-act', '面板检定 ' + ev.id + ' ' + a.action)
      await persist()
      return { ok: true, eventId: ev.id, status: ev.status, verdict: a.verdict, certainty: a.certainty || '可能' }
    })
    harness.handle('scene-end', async (args) => {
      await ensureLoaded()
      const a = args || {}
      const scene = a.scene_id ? findScene(a.scene_id) : activeScene()
      if (!scene) return { ok: false, message: '没有活动场景' }
      if (scene.status !== 'open') return { ok: false, message: '场景已收束' }
      scene.resolution = a.resolution || ''
      scene.threads = (a.threads || []).slice()
      scene.status = 'closed'
      scene.closedAt = clock()
      if (state.session.activeSceneId === scene.id) { state.session.activeSceneId = ''; state.session.mode = 'idle' }
      pushLog('scene-end', '面板收束场景 ' + scene.id)
      await persist()
      return { ok: true, id: scene.id, checks: (scene.checks || []).length }
    })
    harness.handle('infer', async (args) => {
      await ensureLoaded()
      const a = args || {}
      const created = scanImpliedSettings()
      state.inferences.push({ id: uid('in'), query: a.query || '自动扫描', domain: a.domain || 'all', gaps: created.length, candidates: created, at: clock() })
      if (state.inferences.length > 100) state.inferences.shift()
      pushLog('infer', '面板推理：候选 ' + created.length)
      await persist()
      return { ok: true, candidates: created }
    })
    harness.handle('setting-propose', async () => {
      await ensureLoaded()
      const created = scanImpliedSettings()
      pushLog('setting-propose', '面板反向推导：新增候选 ' + created.length)
      await persist()
      return { ok: true, candidates: created }
    })
    harness.handle('candidate-decide', async (args) => {
      await ensureLoaded()
      const a = args || {}
      const c = findCandidate(a.id)
      if (!c) return { ok: false, message: '候选不存在：' + a.id }
      if (c.status !== 'pending') return { ok: false, message: '候选已处理' }
      if (!a.accept) {
        c.status = 'rejected'
        pushLog('candidate-decide', '面板忽略候选 ' + c.id)
        await persist()
        return { ok: true }
      }
      if (c.kind === '新建设定' || c.kind === '补全势力') {
        const name = (a.card && a.card.name) || (c.proposed && c.proposed.name) || ''
        if (!name) return { ok: false, message: '新建设定需要提供名称' }
        const card = { id: uid('s'), type: (a.card && a.card.type) || (c.proposed && c.proposed.type) || 'other', name: name, summary: (a.card && a.card.summary) || ('由候选 ' + c.id + ' 建立：' + c.reason), fields: (a.card && a.card.fields) || [], relations: [], tags: ['候选'] }
        state.settings.push(card)
        c.status = 'accepted'; c.resultId = card.id
        pushLog('candidate-decide', '面板采纳建卡 ' + card.id + ' ' + card.name)
      } else if (c.kind === '补全人物' || c.kind === '新增字段') {
        const card = findSetting((c.proposed && c.proposed.id) || '')
        if (!card) return { ok: false, message: '目标卡不存在' }
        const keys = (card.fields || []).map((f) => f.split(/[：:]/)[0].trim())
        ;(a.card && a.card.fields || []).forEach((f) => {
          const k = f.split(/[：:]/)[0].trim()
          if (k && !keys.includes(k)) card.fields.push(f)
        })
        c.status = 'accepted'; c.resultId = card.id
        pushLog('candidate-decide', '面板采纳补卡 ' + card.id)
      } else {
        c.status = 'accepted'
      }
      await persist()
      return { ok: true, resultId: c.resultId || '' }
    })
  },
}

